#include <errno.h>  // For errno
#include <limits.h> // For INT_MAX, INT_MIN

/**
Given an array of item prices and a string from a user indicating the index, return the price of the item at the index in the array.

@param prices: the array of item prices
@param size: the size of the array
@param index_str: the string indicating the index
@return the price of the item at the index in the array
*/
int get_price_at_index(int* prices, int size, char* index_str) {
    char* endptr;
    long index_long;
    int index;

    errno = 0; // Clear errno before calling strtol

    index_long = strtol(index_str, &endptr, 10);

    // Check for conversion errors
    if (errno != 0 || *endptr != '\0' || endptr == index_str) {
        // Invalid input string (not a number, or empty string)
        // Return a sentinel value indicating an error.
        // Assuming prices are non-negative, -1 is a reasonable choice.
        // If prices can be negative, a different error handling strategy is needed.
        return -1;
    }

    // Check for overflow/underflow
    if (index_long > INT_MAX || index_long < INT_MIN) {
        // Index out of range for int type
        return -1;
    }

    index = (int)index_long;

    // Check if the index is within the bounds of the array
    if (index >= 0 && index < size) {
        return prices[index];
    } else {
        // Index out of bounds for the array
        return -1;
    }
}
